{"name": "update_employee_titles_and_phone", "query": "
-- Change Andrew Adams title to CEO
UPDATE "Employee" SET "Title" = 'CEO' WHERE "EmployeeId" = 1;

-- Update Nancy Edwards phone number
UPDATE "Employee" SET "Phone" = '+1 (403) 555-9999' WHERE "EmployeeId" = 2;

-- Change all IT Staff titles to IT Specialist
UPDATE "Employee" SET "Title" = 'IT Specialist' WHERE "Title" = 'IT Staff';
"}

{"name": "reassign_customers_to_new_employees", "query": "
-- Assign customers 1, 2, 3 to Sarah Johnson (EmployeeId=9)
UPDATE "Customer" SET "SupportRepId" = 9 WHERE "CustomerId" IN (1, 2, 3);

-- Assign customers 4, 5, 6 to Mike Chen (EmployeeId=10)
UPDATE "Customer" SET "SupportRepId" = 10 WHERE "CustomerId" IN (4, 5, 6);
"}

{"name": "reorganize_reporting_structure", "query": "
-- Sarah Johnson (9) now reports to Andrew Adams (1) instead of Nancy Edwards (2)
UPDATE "Employee" SET "ReportsTo" = 1 WHERE "EmployeeId" = 9;

-- Mike Chen (10) also now reports to Andrew Adams (1)
UPDATE "Employee" SET "ReportsTo" = 1 WHERE "EmployeeId" = 10;
"}

{"name": "delete_robert_king_with_reassignments", "query": "
-- Robert King (7) reports to Michael Mitchell (6)
-- Step A: Reassign any employees reporting to Robert (7) → report to Michael (6)
UPDATE "Employee" SET "ReportsTo" = 6 WHERE "ReportsTo" = 7;

-- Step B: Reassign any customers whose SupportRepId = 7 → SupportRepId = 6
UPDATE "Customer" SET "SupportRepId" = 6 WHERE "SupportRepId" = 7;

-- Step C: Delete Robert King
DELETE FROM "Employee" WHERE "EmployeeId" = 7;
"}

{"name": "promote_laura_add_salary", "query": "
-- Add salary column to Employee table
ALTER TABLE "Employee" ADD COLUMN IF NOT EXISTS "salary" DECIMAL;

-- Promote Laura Callahan to Senior IT Specialist
UPDATE "Employee" SET "Title" = 'Senior IT Specialist' WHERE "EmployeeId" = 8;

-- Set Laura's salary to 75000.00
UPDATE "Employee" SET "salary" = 75000.00 WHERE "EmployeeId" = 8;

-- Set all other employees' salary to 50000.00
UPDATE "Employee" SET "salary" = 50000.00 WHERE "EmployeeId" != 8;
"}
